import { PASSWORD, USERS, expect, test } from "../../fixtures";

test.describe("Sign in", () => {
  test(
    "successful sign-in returns a session",
    { tag: "@AUTH-01" },
    async ({ request }) => {
      // Act
      const response = await request.post("/api/auth/login", {
        data: { email: USERS.member, password: PASSWORD },
      });

      // Assert: status
      expect(response.status()).toBe(200);

      // Assert: access token in the response body
      const body = (await response.json()) as { access_token?: unknown };
      expect(typeof body.access_token).toBe("string");
      expect((body.access_token as string).length).toBeGreaterThan(0);

      // Assert: session cookie set as HttpOnly
      const sessionCookie = response
        .headersArray()
        .filter((h) => h.name.toLowerCase() === "set-cookie")
        .find((h) => h.value.startsWith("session="));
      expect(sessionCookie, "a session cookie is set").toBeDefined();
      expect(sessionCookie?.value.toLowerCase()).toContain("httponly");
    },
  );
});

export { expect };
